import re

def parse_duration(duration: str) -> int:
    if not duration:
        return 0
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    for match in re.finditer(r'(\d+)([dhms])', duration):
        total += int(match.group(1)) * units[match.group(2)]
    return total

